use atlas_sqlcipher_proof::{Vault,publication::publish_ciphertext};use atlas_faiss_probe::Index;use serde_json::json;use std::fs::{self,File};
#[test]fn encrypted_snapshot_then_fd_publication_preserves_all_content(){let dir=std::env::temp_dir().join(format!("atlas-snapshot-publish-{}",uuid::Uuid::new_v4()));fs::create_dir(&dir).unwrap();let out=dir.join("out");fs::create_dir(&out).unwrap();let src=dir.join("source");let stage=dir.join("staging");let final_path=out.join("export.atlas");let mut v=Vault::create(&src,"test-password").unwrap();v.put_note("note","SnapshotTitle48917","SnapshotBody48917").unwrap();v.put_file("file","sample.bin",&b"SnapshotFileBytes48917"[..],None).unwrap();v.record_history(json!({"query":"SnapshotQuery48917","mode":"rag","answer":"SnapshotAnswer48917"})).unwrap();let mut idx=Index::new().unwrap();let mut vector=[0f32;512];vector[4]=1.;idx.add(&[vector]).unwrap();v.save_index(&idx).unwrap();let history=v.history_entries().unwrap();v.snapshot_to(&stage,"test-password",|_,_|{}).unwrap();publish_ciphertext(File::open(&stage).unwrap(),File::open(&out).unwrap(),"export.atlas").unwrap();let original=fs::read(&final_path).unwrap();assert!(publish_ciphertext(File::open(&stage).unwrap(),File::open(&out).unwrap(),"export.atlas").is_err());assert_eq!(fs::read(&final_path).unwrap(),original);assert!(Vault::open(&final_path,"wrong-password").is_err());let copy=Vault::open(&final_path,"test-password").unwrap();assert_eq!(copy.get_note("note").unwrap(),"SnapshotBody48917");let mut file=vec![];copy.read("file",&mut file).unwrap();assert_eq!(file,b"SnapshotFileBytes48917");assert_eq!(copy.history_entries().unwrap(),history);assert_eq!(copy.load_index().unwrap().reconstruct(0).unwrap(),vector);assert_eq!(v.get_note("note").unwrap(),"SnapshotBody48917");drop(copy);drop(v);for path in [src,stage,final_path]{let bytes=fs::read(path).unwrap();for marker in ["SnapshotTitle48917","SnapshotBody48917","SnapshotFileBytes48917","SnapshotQuery48917","SnapshotAnswer48917","test-password"] {assert!(!bytes.windows(marker.len()).any(|x|x==marker.as_bytes()));}}fs::remove_dir_all(dir).unwrap();}
